"""Request-local error policy for reads preceding destructive maintenance."""

from contextlib import contextmanager
from contextvars import ContextVar
from typing import Iterator

_strict_reads = ContextVar("mcp_storage_strict_reads", default=False)


def should_raise_read_error() -> bool:
    """Whether this task must propagate read errors instead of empty fallbacks."""
    return _strict_reads.get()


@contextmanager
def strict_reads() -> Iterator[None]:
    """Prevent read failures looking like empty stores in this task only."""
    token = [REDACTED]
    try:
        yield
    finally:
        _strict_reads.reset(token)

#!/usr/bin/env bash
# Test harness for scripts/ci/check_hooks_config_secrets.sh
# Plain bash, same shape as test_plugin_version_check.sh (bats not available).
#
# Tests are self-contained: each one writes a throwaway config JSON in
# $TMPDIR_LOCAL and points the script at it via MCS_HOOKS_CONFIG. Nothing
# depends on the real claude-hooks/config.json, so the tests do not rot when it
# gains or loses fields.

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
SCRIPT="$REPO_ROOT/scripts/ci/check_hooks_config_secrets.sh"
TMPDIR_LOCAL="$(mktemp -d)"

PASS=0
FAIL=0

run_test() {
  local name="$1"
  shift
  if "$@" 2>&1; then
    echo "ok - $name"
    PASS=$((PASS + 1))
  else
    echo "not ok - $name"
    FAIL=$((FAIL + 1))
  fi
}

# Write a config fixture. $1 is the file name, $2 the JSON body.
write_config() {
  local file="$TMPDIR_LOCAL/$1"
  printf '%s\n' "$2" > "$file"
  echo "$file"
}

check() {
  ( cd "$REPO_ROOT" && MCS_HOOKS_CONFIG="$1" bash "$SCRIPT" )
}

test_placeholder_config_passes() {
  local cfg
  cfg="$(write_config clean.json '{
    "memoryService": {
      "http": {"endpoint": "http://127.0.0.1:8000", "apiKey": "auto-detect"},
      "mcp": {"serverCommand": ["uv", "run", "memory"], "serverWorkingDir": null}
    }
  }')"
  check "$cfg" >/dev/null
}

test_real_api_key_fails() {
  local cfg out
  cfg="$(write_config leaked-key.json '{
    "memoryService": {"http": {"apiKey": "[REDACTED]"}}
  }')"
  if out="$(check "$cfg" 2>&1)"; then return 1; fi
  printf '%s' "$out" | grep -q "real-looking credential"
}

test_local_path_fails() {
  local cfg out
  cfg="$(write_config leaked-path.json '{
    "memoryService": {"mcp": {"serverWorkingDir": "/home/someone/repositories/mcp-memory-service"}}
  }')"
  if out="$(check "$cfg" 2>&1)"; then return 1; fi
  printf '%s' "$out" | grep -q "absolute local path"
}

test_windows_path_fails() {
  local cfg out
  cfg="$(write_config leaked-winpath.json '{
    "memoryService": {"mcp": {"serverWorkingDir": "C:\\Users\\someone\\mcp-memory-service"}}
  }')"
  if out="$(check "$cfg" 2>&1)"; then return 1; fi
  printf '%s' "$out" | grep -q "absolute local path"
}

# A nested secret must be found too - the leak was two levels deep.
test_nested_token_fails() {
  local cfg out
  cfg="$(write_config nested-token.json '{
    "sessionHarvest": {"llm": {"groqToken": "[REDACTED]"}}
  }')"
  if out="$(check "$cfg" 2>&1)"; then return 1; fi
  printf '%s' "$out" | grep -q "real-looking credential"
}

# A JWT's dots put it outside any sane character class - the shape check must be
# "no whitespace", not an allow-list. Mira flagged this false negative on #200.
test_jwt_fails() {
  local cfg out
  cfg="$(write_config leaked-jwt.json '{
    "memoryService": {"http": {"apiKey": "[REDACTED]"}}
  }')"
  if out="$(check "$cfg" 2>&1)"; then return 1; fi
  printf '%s' "$out" | grep -q "real-looking credential"
}

# Punctuation-heavy secrets must not slip through either.
test_punctuation_secret_fails() {
  local cfg out
  cfg="$(write_config leaked-punct.json '{
    "sessionHarvest": {"llm": {"apiSecret": "[REDACTED]}[]|:;<>,.?~-="}}
  }')"
  if out="$(check "$cfg" 2>&1)"; then return 1; fi
  printf '%s' "$out" | grep -q "real-looking credential"
}

# A key whose NAME matches the secret pattern but whose value is a URL is a
# legitimate config value - tokenEndpoint, not a token.
test_url_under_secret_named_key_passes() {
  local cfg
  cfg="$(write_config token-endpoint.json '{
    "oauth": {"tokenEndpoint": "https://auth.example.com/oauth2/v2/token"}
  }')"
  check "$cfg" >/dev/null
}

# Prose under a secret-named key contains spaces, so it must not trip the gate.
test_prose_under_secret_named_key_passes() {
  local cfg
  cfg="$(write_config prose.json '{
    "memoryService": {"http": {"apiKeyHint": "set this to the same value as MCP_API_KEY on your server"}}
  }')"
  check "$cfg" >/dev/null
}

# Relative paths and URLs are legitimate config values, not leaks.
test_relative_paths_and_urls_pass() {
  local cfg
  cfg="$(write_config relative.json '{
    "memoryService": {
      "http": {"endpoint": "https://memory.example.com:8443", "apiKey": ""},
      "mcp": {"serverWorkingDir": "./scripts", "serverCommand": ["uv", "run", "memory"]}
    }
  }')"
  check "$cfg" >/dev/null
}

# Short, human-readable values under a secret-ish name are placeholders, not keys.
test_short_placeholder_key_passes() {
  local cfg
  cfg="$(write_config short-key.json '{
    "memoryService": {"http": {"apiKey": "[REDACTED]"}}
  }')"
  check "$cfg" >/dev/null
}

test_missing_config_fails() {
  local out
  if out="$(check "$TMPDIR_LOCAL/does-not-exist.json" 2>&1)"; then return 1; fi
  printf '%s' "$out" | grep -q "not found"
}

test_unparseable_config_fails() {
  local cfg out
  cfg="$(write_config broken.json '{ this is not json')"
  if out="$(check "$cfg" 2>&1)"; then return 1; fi
  printf '%s' "$out" | grep -q "could not parse"
}

# The real shipped config must satisfy the gate.
test_repository_config_passes() {
  ( cd "$REPO_ROOT" && bash "$SCRIPT" ) >/dev/null
}

run_test "placeholder config passes"                     test_placeholder_config_passes
run_test "committed api key fails"                       test_real_api_key_fails
run_test "absolute posix path fails"                     test_local_path_fails
run_test "absolute windows path fails"                   test_windows_path_fails
run_test "nested token fails"                            test_nested_token_fails
run_test "jwt fails (dots are not in any allow-list)"    test_jwt_fails
run_test "punctuation-heavy secret fails"                test_punctuation_secret_fails
run_test "url under a secret-named key passes"           test_url_under_secret_named_key_passes
run_test "prose under a secret-named key passes"         test_prose_under_secret_named_key_passes
run_test "relative paths and urls pass"                  test_relative_paths_and_urls_pass
run_test "short placeholder key passes"                  test_short_placeholder_key_passes
run_test "missing config is reported"                    test_missing_config_fails
run_test "unparseable config is reported"                test_unparseable_config_fails
run_test "the repository's own config passes"            test_repository_config_passes

rm -rf "$TMPDIR_LOCAL"

echo ""
echo "Results: $PASS passed, $FAIL failed"
[ "$FAIL" -eq 0 ]

"""Schema migration runner with version tracking and registry."""

import hashlib
import locale
import logging
import re
import sqlite3
from datetime import datetime, timezone
from pathlib import Path

logger = logging.getLogger(__name__)

# Pattern: NNN_description.sql (e.g., 008_add_graph_table.sql)
MIGRATION_FILE_PATTERN = re.compile(r"^(\d{3})_(.+)\.sql$")


class MigrationRunner:
    """Schema migration runner with version tracking and registry."""

    def __init__(self, migrations_dir: Path):
        self.migrations_dir = migrations_dir

    def _discover_migrations(self) -> list[tuple[int, str, Path]]:
        """Discover migration files sorted by version number.
        Returns: [(version, name, path), ...]
        """
        migrations = []
        if not self.migrations_dir.exists():
            return migrations
        for f in self.migrations_dir.iterdir():
            m = MIGRATION_FILE_PATTERN.match(f.name)
            if m:
                version = int(m.group(1))
                name = m.group(2)
                migrations.append((version, name, f))
        return sorted(migrations, key=lambda x: x[0])

    def _ensure_registry_table(self, conn):
        """Create migration_registry table if it doesn't exist."""
        conn.execute("""
            CREATE TABLE IF NOT EXISTS migration_registry (
                version INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                filename TEXT NOT NULL,
                applied_at TEXT NOT NULL,
                checksum TEXT
            )
        """)

    def _ensure_metadata_table(self, conn):
        """Create the metadata table that holds schema_version (#1628).

        The runner records `schema_version` there after every migration, but only
        `SqliteVecMemoryStorage.initialize()` used to create the table. `memory
        migrate` calls `run_pending()` on a plain `sqlite3.connect()` and never went
        through `initialize()`, so on a database written before v8.7.0 the write
        failed, the rollback took the migration that had just applied down with it,
        and every later migration was skipped.

        Creating it here covers both callers. Same definition the storage uses.
        """
        conn.execute("""
            CREATE TABLE IF NOT EXISTS metadata (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            )
        """)

    def _get_applied_versions(self, conn) -> set[int]:
        """Read migration_registry to find already-applied versions."""
        try:
            cursor = conn.execute("SELECT version FROM migration_registry")
            return {row[0] for row in cursor.fetchall()}
        except sqlite3.OperationalError:
            return set()

    def _get_registry(self, conn) -> list[dict]:
        """Read full migration registry."""
        try:
            cursor = conn.execute(
                "SELECT version, name, filename, applied_at, checksum FROM migration_registry ORDER BY version"
            )
            return [
                {"version": r[0], "name": r[1], "filename": r[2], "applied_at": r[3], "checksum": r[4]}
                for r in cursor.fetchall()
            ]
        except sqlite3.OperationalError:
            return []

    def _get_current_version(self, conn) -> int:
        """Read schema_version from metadata. Default 7 if missing."""
        try:
            cursor = conn.execute("SELECT value FROM metadata WHERE key='schema_version'")
            row = cursor.fetchone()
            return int(row[0]) if row else 7
        except sqlite3.OperationalError:
            return 7

    @staticmethod
    def _read_sql(path: Path) -> str:
        """Read a migration file as UTF-8, the encoding the files are written in.

        Without an explicit encoding Python on Windows (before 3.15) decodes with
        the locale code page, and cp950/cp949 cannot decode the UTF-8 punctuation
        in 008 and 010, which stopped every later migration (#1789).
        """
        return path.read_text(encoding="utf-8")

    def _checksum(self, path: Path) -> str:
        """SHA256 checksum of migration file content."""
        return hashlib.sha256(self._read_sql(path).encode()).hexdigest()

    @staticmethod
    def _legacy_checksum(path: Path) -> str | None:
        """Checksum as runners before #1789 recorded it on this machine.

        They decoded with the locale encoding. Where that is not UTF-8 but could
        still decode the file (cp1252, for one), the stored checksum hashes the
        mis-decoded text and must not be reported as a modified migration.
        """
        encoding = locale.getpreferredencoding(False)
        try:
            return hashlib.sha256(path.read_text(encoding=encoding).encode()).hexdigest()
        except (UnicodeDecodeError, LookupError):
            return None

    def _stamp_baseline(self, conn) -> list[int]:
        """Stamp pre-existing migrations as applied without re-executing.

        On existing databases, migrations 008-011 were applied by the old
        idempotent runner (which swallowed duplicate-column errors). We detect
        their artifacts and register them so run_pending() skips them.

        Returns list of stamped versions.
        """
        applied = set(self._get_applied_versions(conn))

        # Independent recovery probes (15/16 delta-sync, 20 belief embedding): probe these
        # INDEPENDENTLY of the legacy baseline below, and only when absent from the registry.
        # A partial manual rollback can leave the primary artifact (table/column) in place
        # while its registry row was removed; without this, the forward migration would re-run
        # the unconditional ADD COLUMN/TABLE and fail duplicate (Greptile). Strict no-op unless
        # the artifact exists AND its registry row is missing — never changes the legacy 8-11
        # baseline semantics handled further down.
        delta_probes = {
            15: "SELECT 1 FROM sqlite_master WHERE type='table' AND name='sync_events'",
            16: "SELECT 1 FROM pragma_table_info('sync_events') WHERE name='hlc_physical'",
            20: "SELECT 1 FROM pragma_table_info('beliefs') WHERE name='embedding'",
        }
        recovered = self._stamp_probes(
            conn, {v: sql for v, sql in delta_probes.items() if v not in applied}
        )
        if recovered:
            # Advance schema_version to the highest recovered migration, but NEVER lower an
            # already-higher value. After the documented partial rollback schema_version is 15;
            # recovering v16 must bump it to 16 so the schema check reports the real state
            # (otherwise run_pending skips v16 and the version stays stale at 15 — Greptile).
            self._raise_schema_version(conn, max(recovered))

        # Legacy baseline (008-011): only on a fresh existing DB with an EMPTY registry, detect
        # artifacts left by the old idempotent runner and stamp them so run_pending skips them.
        # Preserved exactly as before (early-return when the registry is already populated).
        if applied:
            return recovered

        probes = {
            8: "SELECT 1 FROM sqlite_master WHERE type='table' AND name='memory_graph'",
            9: "SELECT 1 FROM pragma_table_info('memory_graph') WHERE name='relationship_type'",
            10: "SELECT 1 FROM sqlite_master WHERE type='table' AND name='memory_graph'",  # graph indexes
            11: "SELECT 1 FROM pragma_table_info('memories') WHERE name='version'",
        }
        stamped = recovered + self._stamp_probes(conn, probes)
        if stamped:
            max_version = max(stamped)
            conn.execute(
                "INSERT OR REPLACE INTO metadata (key, value) VALUES ('schema_version', ?)",
                (str(max_version),),
            )
            conn.commit()
            logger.info(f"Baseline stamp: registered migrations {stamped} (existing DB detected)")

        return stamped

    def _stamp_probes(self, conn, probes: dict) -> list[int]:
        """Stamp each probed version whose artifact exists but whose registry row is missing.

        Shared by the delta-sync recovery and the legacy 8-11 baseline. Does NOT touch
        schema_version (callers decide); commits only the registry inserts it performs.

        Before stamping, repairs any SECONDARY artifact a partial rollback may have dropped
        while the primary artifact (the probed column/table) was retained — otherwise the
        migration is marked applied forever but a dropped index/trigger never comes back.
        Repairs are idempotent (IF NOT EXISTS).

        Returns the list of versions stamped.
        """
        if not probes:
            return []

        # Idempotent repairs for secondary artifacts, keyed by migration version. The primary
        # artifact is detected by the probe; these restore the rest (e.g. the HLC index that a
        # rollback dropped alongside the retained hlc columns — Greptile).
        artifact_repairs = {
            16: "CREATE INDEX IF NOT EXISTS idx_sync_events_hlc "
                "ON sync_events(hlc_physical, hlc_logical, agent_id, event_id)",
            20: "CREATE INDEX IF NOT EXISTS idx_beliefs_embedding_pending "
                "ON beliefs(belief_hash) WHERE embedding IS NULL",
        }

        stamped = []
        now = datetime.now(timezone.utc).isoformat()
        migrations = self._discover_migrations()
        migrations_by_version = {v: (n, p) for v, n, p in migrations}

        for version, probe_sql in probes.items():
            try:
                cursor = conn.execute(probe_sql)
                if cursor.fetchone():
                    # Secondary-artifact repair (idempotent) before stamping.
                    repair_sql = artifact_repairs.get(version)
                    if repair_sql:
                        conn.execute(repair_sql)
                    # Artifact exists — stamp as applied
                    name, path = migrations_by_version.get(version, (f"legacy_{version}", None))
                    checksum = self._checksum(path) if path else ""
                    filename = path.name if path else f"{version:03d}_unknown.sql"
                    conn.execute(
                        "INSERT OR IGNORE INTO migration_registry (version, name, filename, applied_at, checksum) VALUES (?, ?, ?, ?, ?)",
                        (version, name, filename, now, checksum),
                    )
                    stamped.append(version)
            except sqlite3.OperationalError:
                continue

        if stamped:
            conn.commit()
        return stamped

    def _raise_schema_version(self, conn, version: int) -> None:
        """Set schema_version to `version`, but never lower an already-higher value.

        Used after recovery stamps a migration (e.g. v16) on a DB whose schema_version was
        left behind by a partial rollback, so the reported version matches reality.
        """
        try:
            cur = conn.execute("SELECT value FROM metadata WHERE key='schema_version'")
            row = cur.fetchone()
            current = int(row[0]) if row and row[0] is not None else 0
        except (sqlite3.OperationalError, ValueError, TypeError):
            current = 0
        if version > current:
            conn.execute(
                "INSERT OR REPLACE INTO metadata (key, value) VALUES ('schema_version', ?)",
                (str(version),),
            )
            conn.commit()

    def run_pending(self, conn, dry_run=False) -> dict:
        """Run all pending migrations in order.

        Returns: {applied: [...], skipped: [...], error: None|str}
        """
        result = {"applied": [], "skipped": [], "error": None}
        try:
            if not dry_run:
                self._ensure_registry_table(conn)
                # `schema_version` lives in `metadata`, and every migration below
                # writes it. Create it here so callers that never initialize()
                # — `memory migrate` — are covered too (#1628).
                self._ensure_metadata_table(conn)
                conn.commit()  # Ensure no open transaction before we begin
                # Stamp pre-existing migrations on upgrade from old runner
                self._stamp_baseline(conn)
            applied_versions = self._get_applied_versions(conn)
            migrations = self._discover_migrations()

            for version, name, path in migrations:
                if version in applied_versions:
                    result["skipped"].append({"version": version, "name": name})
                    continue

                if dry_run:
                    result["applied"].append({"version": version, "name": name})
                    continue

                sql = self._read_sql(path)
                checksum = self._checksum(path)
                now = datetime.now(timezone.utc).isoformat()

                try:
                    conn.execute("BEGIN")
                    # Execute each statement individually (not executescript which auto-commits)
                    for statement in self._split_sql(sql):
                        conn.execute(statement)
                    conn.execute(
                        "INSERT INTO migration_registry (version, name, filename, applied_at, checksum) VALUES (?, ?, ?, ?, ?)",
                        (version, name, path.name, now, checksum),
                    )
                    conn.execute(
                        "INSERT OR REPLACE INTO metadata (key, value) VALUES ('schema_version', ?)",
                        (str(version),),
                    )
                    conn.execute("COMMIT")
                    result["applied"].append({"version": version, "name": name})
                    logger.info(f"Migration {version:03d}_{name} applied successfully")
                except Exception as e:
                    conn.execute("ROLLBACK")
                    result["error"] = f"Migration {version:03d}_{name} failed: {e}"
                    logger.error(result["error"])
                    break

        except Exception as e:
            result["error"] = str(e)
        return result

    def check(self, conn) -> dict:
        """Diagnosis only (safe for read-only/locked DB).

        Returns: {current_version, pending: [...], registry: [...], healthy: bool, checksum_mismatches: [...]}
        """
        current_version = self._get_current_version(conn)
        registry = self._get_registry(conn)
        applied_versions = {r["version"] for r in registry}
        migrations = self._discover_migrations()

        pending = [
            {"version": v, "name": n, "filename": p.name}
            for v, n, p in migrations
            if v not in applied_versions
        ]

        # Check for checksum mismatches
        checksum_mismatches = []
        registry_by_version = {r["version"]: r for r in registry}
        for version, name, path in migrations:
            if version in registry_by_version:
                stored = registry_by_version[version].get("checksum")
                if stored and stored not in (self._checksum(path), self._legacy_checksum(path)):
                    checksum_mismatches.append({"version": version, "name": name, "filename": path.name})

        healthy = len(pending) == 0 and len(checksum_mismatches) == 0

        return {
            "current_version": current_version,
            "pending": pending,
            "registry": registry,
            "healthy": healthy,
            "checksum_mismatches": checksum_mismatches,
        }

    @staticmethod
    def _split_sql(sql: str) -> list[str]:
        """Split SQL text into individual statements, skipping empty/transaction control ones."""
        # Transaction control is handled by the runner, skip them in migration files
        skip_keywords = {"begin", "begin transaction", "commit", "rollback"}
        statements = []
        for stmt in sql.split(";"):
            stmt = stmt.strip()
            # Remove leading comment lines
            lines = [l for l in stmt.splitlines() if not l.strip().startswith("--")]
            clean = "\n".join(lines).strip()
            if clean and clean.lower() not in skip_keywords:
                statements.append(stmt)
        return statements

-- Migration 008: Add graph-based memory associations table
-- Supports triple storage modes: memories_only (backward compat), dual_write (migration), graph_only (future)
-- Connection types: semantic (0.3-0.7), temporal (<24h), causal (explicit refs), thematic (shared tags)

CREATE TABLE IF NOT EXISTS memory_graph (
    source_hash TEXT NOT NULL,
    target_hash TEXT NOT NULL,
    similarity REAL NOT NULL,
    connection_types TEXT NOT NULL,  -- JSON array: ["semantic", "temporal", "causal", "thematic"]
    metadata TEXT,                   -- JSON object: {discovery_date, confidence, context}
    created_at REAL NOT NULL,
    PRIMARY KEY (source_hash, target_hash)
);

-- Optimize bidirectional traversal (A→B and B→A queries)
-- Note: PRIMARY KEY already creates an index on (source_hash, target_hash)
CREATE INDEX IF NOT EXISTS idx_graph_source ON memory_graph(source_hash);
CREATE INDEX IF NOT EXISTS idx_graph_target ON memory_graph(target_hash);
